function mobileSportEvents(data,league){return(Array.isArray(data?.events)?data.events:[]).map(e=>{const c=e.competitions?.[0],h=c?.competitors?.find(x=>x.homeAway==='home'),a=c?.competitors?.find(x=>x.homeAway==='away');if(!h||!a||!Number.isFinite(Date.parse(e.date)))return null;const team=x=>({id:String(x.team?.id||''),name:String(x.team?.shortDisplayName||x.team?.displayName||''),logo:String(x.team?.logo||''),score:String(x.score??'')});return{id:String(e.id||''),league,date:e.date,state:String(e.status?.type?.state||'pre'),detail:String(e.status?.type?.shortDetail||''),home:team(h),away:team(a)};}).filter(Boolean).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));}
