function mobileParseCsMatches(rows,now=Date.now()){
  const found=new Map();for(const row of Array.isArray(rows)?rows:[]){const x=row?.mc_info,st=row?.state,code=String(st?.status??''),start=Number(x?.plan_ts)*1000,id=String(x?.id||''),a=String(x?.t1_info?.disp_name||'').trim(),b=String(x?.t2_info?.disp_name||'').trim();if(!/^csgo_mc_\d+$/.test(id)||!['-1','0','1'].includes(code)||!a||!b||/^(?:tbd|unknown|待定|\?)$/i.test(a)||/^(?:tbd|unknown|待定|\?)$/i.test(b)||!Number.isFinite(start))continue;const live=code==='1';if(live?(start<now-86400000||start>now+3600000):(start<now||start>now+7*86400000))continue;const logo=v=>{try{const u=new URL(String(v||''));return u.protocol==='https:'&&u.hostname==='oss.5eplay.com'&&!u.pathname.endsWith('/null.png')?u.href:'';}catch{return '';}};const score=v=>/^\d{1,2}$/.test(String(v??''))?String(v):'';const t=String(row?.tt_info?.abbr_en||row?.tt_info?.disp_name||'').replace(/\p{Script=Han}+/gu,' ').replace(/\s+/g,' ').trim();found.set(id,{id,home:a.slice(0,100),away:b.slice(0,100),homeLogo:logo(x.t1_info?.logo),awayLogo:logo(x.t2_info?.logo),homeScore:live?score(st.t1_score):'',awayScore:live?score(st.t2_score):'',date:start,live,league:/[a-z]/i.test(t)?t.slice(0,100):'CS2 · 5EPlay'});}
  return [...found.values()].sort((a,b)=>Number(b.live)-Number(a.live)||a.date-b.date).slice(0,40);
}

async function mobileEsportCs(){const pages=await Promise.allSettled([1,2].map(async page=>{const u='https://app.5eplay.com/api/tournament/session_list?game_status=1&game_type=1&grades=&page='+page+'&limit=20';const r=await fetch(tvPx(u,'','',true),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP');const j=await r.json();if(j.success!==true||!Array.isArray(j.data?.matches))throw Error('SCHEMA');return j.data.matches;}));const good=pages.filter(x=>x.status==='fulfilled');if(!good.length)throw Error('NETWORK');return {items:mobileParseCsMatches(good.flatMap(x=>x.value)),partial:good.length<pages.length};}

