const MOBILE_SPORT_FIRED='luma.sport.reminders.fired.v1';
let mobileReminderLast='';
function mobileReminderNativeEnabled(){try{return !!NATIVE?.remindersEnabled?.();}catch{return false;}}
function mobileReminderExactEnabled(){try{return !!NATIVE?.remindersExactEnabled?.();}catch{return false;}}
function mobileReminderHint(){return mobileReminderNativeEnabled()?(mobileReminderExactEnabled()?'Напомним за 15 минут. В фоне уведомление может задержаться из-за настроек телефона.':'Уведомление в фоне может задержаться даже после разрешения точного времени. Чтобы уменьшить задержку, разрешите будильники в настройках.'):'Разрешите уведомления для работы в фоне; иначе напомним только при открытой Luma.';}
function mobileSyncReminders(force=false){if(!NATIVE?.remindersSync)return;const shown=mobileSportReminderFired();const entries=Object.values(S.extra?.syncForeign?.sportReminders||{}).filter(x=>x?.on&&Number.isFinite(Number(x.startsAt))&&Number(x.startsAt)>Date.now()-3600000).map(x=>({id:String(x.id||''),title:String(x.title||''),startsAt:Number(x.startsAt),endsAt:Number(x.endsAt)||0,kind:String(x.kind||''),subtitle:String(x.kind==='tv'?x.channelName||'':x.league||''),shown:!!shown[String(x.id||'')+':'+Number(x.startsAt)]}));const raw=JSON.stringify(entries);if(!force&&raw===mobileReminderLast)return;NATIVE.remindersSync(raw);mobileReminderLast=raw;}
window.lumaReminderPermissionChanged=()=>{mobileReminderLast='';mobileSyncReminders(true);const sheet=document.querySelector('.sheet:not(.out)');if(!sheet)return;for(const prefix of ['reminder','tv-reminder']){const hint=sheet.querySelector('[data-'+prefix+'-hint]'),settings=sheet.querySelector('[data-'+prefix+'-settings]'),exact=sheet.querySelector('[data-'+prefix+'-exact]');if(hint)hint.textContent=mobileReminderHint();if(settings)settings.hidden=mobileReminderNativeEnabled();if(exact)exact.hidden=!mobileReminderNativeEnabled()||mobileReminderExactEnabled();}};
