function mobileSportReminderStore(){const x=((S.extra ||= {}).syncForeign ||= {});return x.sportReminders ||= {};}
function mobileSportReminderKey(m){return 'match:'+encodeURIComponent(String(m.league||''))+':'+encodeURIComponent(String(m.id||''));}
function mobileSportReminderFired(){try{const x=JSON.parse(localStorage.getItem(MOBILE_SPORT_FIRED)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{};}catch{return {};}}
function mobileSportReminderTick(now=Date.now()){if(document.hidden)return;const fired=mobileSportReminderFired();let dirty=false;for(const [key,item] of Object.entries(mobileSportReminderStore())){const start=Number(item?.startsAt),end=Number(item?.endsAt),deadline=item?.kind==='tv'&&Number.isFinite(end)&&end>start?Math.min(start+3600000,end):start+3600000,marker=key+':'+start;if(!item?.on||!Number.isFinite(start)||now<start-900000||now>=deadline||fired[marker])continue;if(mobileReminderNativeEnabled()&&NATIVE?.remindersMarkShown&&!NATIVE.remindersMarkShown(key,start))continue;fired[marker]=now;dirty=true;const time=new Date(start).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});toast(item.title+' · '+(now<start?'начало в ':'начало было в ')+time);}if(dirty)try{localStorage.setItem(MOBILE_SPORT_FIRED,JSON.stringify(Object.fromEntries(Object.entries(fired).filter(([,at])=>Number(at)>now-90*86400000).sort((a,b)=>b[1]-a[1]).slice(0,500))));}catch{}if(dirty)mobileSyncReminders(true);}
function mobileSportToggleReminder(m){const all=mobileSportReminderStore(),key=mobileSportReminderKey(m),old=all[key],on=!old?.on,start=Date.parse(m.date);all[key]={id:key,league:String(m.league||''),title:String(m.home?.name||'')+' — '+String(m.away?.name||''),startsAt:start,on,ts:Math.max(Date.now(),Number(old?.ts||0)+1)};if(on){const fired=mobileSportReminderFired();delete fired[key+':'+start];try{localStorage.setItem(MOBILE_SPORT_FIRED,JSON.stringify(fired));}catch{}}save();if(on){mobileSyncReminders();mobileAskReminderPermission();setTimeout(mobileSportReminderTick,100);}return on;}
setTimeout(mobileSportReminderTick,5000);setInterval(mobileSportReminderTick,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)mobileSportReminderTick();});
function mobileSportFollowStore(){const x=((S.extra ||= {}).syncForeign ||= {});return x.sportFollows ||= {};}
function mobileSportLeagueGroup(league){return ['РПЛ','АПЛ','Лига чемпионов','Ла Лига'].includes(league)?'soccer':league==='НБА'?'basketball':league==='НХЛ'?'hockey':league==='НФЛ'?'football':league==='МЛБ'?'baseball':String(league||'').trim().toLowerCase();}
function mobileSportFollowKey(kind,league,name='',teamId=''){if(kind==='team'&&/^\d+$/.test(String(teamId)))return 'team:'+mobileSportLeagueGroup(league)+':'+teamId;return kind+':'+encodeURIComponent(String(league||'').trim().toLowerCase())+(kind==='team'?':'+encodeURIComponent(String(name||'').trim().toLowerCase()):'');}
function mobileSportIsFollowed(kind,league,name='',teamId=''){return !!mobileSportFollowStore()[mobileSportFollowKey(kind,league,name,teamId)]?.on;}
function mobileSportToggleFollow(kind,league,name='',teamId=''){const all=mobileSportFollowStore(),key=mobileSportFollowKey(kind,league,name,teamId),old=all[key];all[key]={kind,league,name,teamId,on:!old?.on,ts:Math.max(Date.now(),Number(old?.ts||0)+1)};save();return all[key].on;}
