async function mobileEsportStreams(match){let raw;if(match.game==='VALORANT'&&/^\/\d{1,12}\/[a-z0-9-]{1,200}$/i.test(String(match.id||''))){const r=await fetch(tvPx('https://www.vlr.gg'+match.id,'','',true),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP');const doc=new DOMParser().parseFromString(await r.text(),'text/html');const dates=doc.querySelectorAll('.match-header-date [data-utc-ts]');match.valorantStart=match.state==='pre'&&dates.length>=2?mobileValorantConfirmedStart(dates[0].textContent,dates[1].textContent,dates[0].getAttribute('data-utc-ts'),doc.querySelector('.match-header-vs-note.mod-upcoming')?.textContent):null;raw=[...doc.querySelectorAll('.match-streams-container .sm-body[data-site-id]')].map(el=>({provider:el.dataset.embedSite,id:el.dataset.siteId,name:el.querySelector('.sm-name')?.textContent.trim()||'Трансляция'}));}else if(match.game==='League of Legends'&&/^\d{1,24}$/.test(String(match.id||''))){const hdr={'x-api-key':'0TvQnueqKa5mxJntVWt0w4LpLfEkrV1Ta8rQBb9Z'},r=await fetch(tvPx('https://esports-api.lolesports.com/persisted/gw/getEventDetails?hl=en-US&id='+match.id,'','',true,hdr),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP');raw=((await r.json()).data?.event?.streams||[]).map(x=>({provider:x.provider,id:x.parameter,name:x.mediaLocale?.translatedName||x.locale||'Трансляция'}));}else return [];const out=[],seen=new Set();for(const x of raw){const provider=String(x.provider||'').toLowerCase(),id=String(x.id||'');if(!(provider==='youtube'&&/^[\w-]{11}$/.test(id)||provider==='twitch'&&/^[a-z0-9_]{3,25}$/i.test(id)))continue;const key=provider+':'+id.toLowerCase();if(seen.has(key))continue;seen.add(key);out.push({provider,id,name:String(x.name||provider).slice(0,100)});}return out.slice(0,20);}
async function mobileEsportPaintStreams(sheet,match){const host=$('[data-esport-streams]',sheet);if(!host)return;try{const entries=await mobileEsportStreams(match);if(sheetEl!==sheet||!host.isConnected)return;host.innerHTML=entries.length?'<p class="mobile-sport-caption">Ссылки источника матча · YouTube в Luma, Twitch в приложении</p><div class="mobile-esport-streams">'+entries.map((x,i)=>`<button data-esport-stream="${i}"><b>${x.provider==='youtube'?'YouTube':'Twitch'}</b><span>${esc(x.name)}</span><i>↗</i></button>`).join('')+'</div>':'<p class="sub">Ссылок на трансляции от источника пока нет.</p>';if(match.game==='VALORANT'&&match.valorantStart){const scheduled={...match,date:new Date(match.valorantStart).toISOString()},active=!!mobileSportReminderStore()[mobileSportReminderKey(scheduled)]?.on;host.insertAdjacentHTML('beforeend',`<div class="mobile-reminder"><button data-valorant-remind aria-pressed="${active}">${active?'Напоминание включено':'Напомнить за 15 минут'}</button><small>${esc(new Date(match.valorantStart).toLocaleString('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}))} · ${esc(mobileReminderHint())}</small></div>`);const button=host.querySelector('[data-valorant-remind]');button.onclick=()=>{if(match.valorantStart<=Date.now()){button.disabled=true;toast('Матч уже начался');return;}const on=mobileSportToggleReminder(scheduled);button.setAttribute('aria-pressed',String(on));button.textContent=on?'Напоминание включено':'Напомнить за 15 минут';};}$$('[data-esport-stream]',host).forEach(b=>b.onclick=()=>{const x=entries[Number(b.dataset.esportStream)];if(!x)return;if(x.provider==='youtube'){closeSheet();openMobileYoutube(x.id);}else NATIVE?.openUrl('https://www.twitch.tv/'+encodeURIComponent(x.id));});}catch{if(sheetEl===sheet&&host.isConnected){host.innerHTML='<p class="sub">Не удалось загрузить ссылки на трансляции. <button class="mobile-search-retry" data-stream-retry>Повторить</button></p>';host.querySelector('[data-stream-retry]').onclick=()=>{host.innerHTML='<p class="sub">Ищем трансляции…</p>';mobileEsportPaintStreams(sheet,match);};}}}
function openMobileEsportMatch(match){const status=match.state==='in'?'Матч идёт':match.eta||new Date(match.date).toLocaleString('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});const score=match.state==='in'?[match.home.score||'—',match.away.score||'—'].join(' : '):'—';const sheet=openSheet(`<span class="mobile-sport-overline">КИБЕРСПОРТ · ${esc(match.game||'CS2')}</span><h3>${esc(match.home.name)} — ${esc(match.away.name)}</h3><p class="mobile-sport-score">${esc(score)}</p><p class="sub">${esc(status)} · ${esc(match.league)}${match.game==='Dota 2'?(String(match.id||'').startsWith('spectate:')?' · счёт серии':' · счёт по убийствам'):''}</p>${Array.isArray(match.killScore)?`<p class="sub">Убийства: ${esc(match.killScore.join(' : '))} · OpenDota</p>`:''}${['CS2','League of Legends'].includes(match.game)&&match.id&&match.state==='pre'&&Date.parse(match.date)>Date.now()?`<div class="mobile-reminder"><button data-esport-remind aria-pressed="${!!mobileSportReminderStore()[mobileSportReminderKey(match)]?.on}">${mobileSportReminderStore()[mobileSportReminderKey(match)]?.on?'Напоминание включено':'Напомнить за 15 минут'}</button><small>${esc(mobileReminderHint())}</small></div>`:''}${['VALORANT','League of Legends'].includes(match.game)?'<div data-esport-streams><p class="sub">Загружаем ссылки на трансляции…</p></div>':''}${Array.isArray(match.broadcasts)&&match.broadcasts.length?'<div data-spectate-streams></div>':''}${match.game==='Dota 2'&&match.state==='in'&&!(Array.isArray(match.broadcasts)&&match.broadcasts.length)?'<div data-dota-lookup><p class="sub">Проверяем ссылки турнира…</p></div>':''}${match.game==='CS2'&&match.state==='in'?'<div data-cito-streams><p class="sub">Проверяем ссылки источника матча…</p></div>':''}${['CS2','Dota 2'].includes(match.game)&&match.state==='in'?'<div data-esport-twitch><p class="sub">Ищем возможные эфиры Twitch…</p></div>':''}<p class="sub">Поиск покажет видео по названиям команд; наличие трансляции не подтверждено.</p><div class="dbtns"><button class="btn" data-esport-close>Закрыть</button><button class="btn primary" data-esport-search>Искать видео</button></div>`);if(['VALORANT','League of Legends'].includes(match.game))mobileEsportPaintStreams(sheet,match);if(match.game==='Dota 2'&&match.state==='in'&&!(Array.isArray(match.broadcasts)&&match.broadcasts.length))mobileDotaFindBroadcasts(sheet,match);if(match.game==='CS2'&&match.state==='in')mobileEsportPaintCito(sheet,match);if(Array.isArray(match.broadcasts)&&match.broadcasts.length){const host=$('[data-spectate-streams]',sheet),streams=match.broadcasts;host.innerHTML='<p class="mobile-sport-caption">Ссылки источника матча · доступность эфира не проверена</p><div class="mobile-esport-streams">'+streams.map((x,i)=>`<button data-spectate-stream="${i}"><b>${x.provider==='youtube'?'YouTube':'Twitch'}</b><span>${esc(x.title)}</span><i>↗</i></button>`).join('')+'</div>';host.querySelectorAll('[data-spectate-stream]').forEach(b=>b.onclick=()=>{const x=streams[Number(b.dataset.spectateStream)];if(!x)return;if(x.provider==='youtube'){closeSheet();openMobileYoutube(x.id);}else NATIVE?.openUrl('https://www.twitch.tv/'+encodeURIComponent(x.id));});}if(['CS2','Dota 2'].includes(match.game)&&match.state==='in')mobileEsportPaintTwitch(sheet,match);const reminder=$('[data-esport-remind]',sheet);if(reminder)reminder.onclick=()=>{const on=mobileSportToggleReminder(match);reminder.setAttribute('aria-pressed',String(on));reminder.textContent=on?'Напоминание включено':'Напомнить за 15 минут';};$('[data-esport-close]',sheet).onclick=closeSheet;$('[data-esport-search]',sheet).onclick=()=>{closeSheet();openMobileShows('rutube',match.home.name+' '+match.away.name+' '+(match.game||'CS2'));};}

function openMobileSportReminders(){const sheet=openSheet('<h3>Напоминания</h3><p class="sub" data-reminder-hint></p><button class="btn" data-reminder-settings hidden>Настроить уведомления</button><button class="btn" data-reminder-exact hidden>Разрешить точное время</button><div data-reminder-list></div><button class="btn" data-reminder-close>Закрыть</button>');const hint=$('[data-reminder-hint]',sheet),settings=$('[data-reminder-settings]',sheet);hint.textContent=mobileReminderHint();settings.hidden=mobileReminderNativeEnabled();settings.onclick=()=>NATIVE?.remindersOpenSettings?.();const exact=$('[data-reminder-exact]',sheet);exact.hidden=!mobileReminderNativeEnabled()||mobileReminderExactEnabled();exact.onclick=()=>NATIVE?.remindersOpenExactSettings?.();const draw=()=>{const now=Date.now(),entries=Object.values(mobileSportReminderStore()).filter(x=>x?.kind!=='tv'&&x?.on&&Number(x.startsAt)>=now-3600000).sort((a,b)=>a.startsAt-b.startsAt),host=$('[data-reminder-list]',sheet);host.innerHTML=entries.length?entries.map((x,i)=>`<button class="mobile-reminder-item" data-reminder-remove="${i}"><span><b>${esc(x.title)}</b><small>${esc(new Date(Number(x.startsAt)).toLocaleString('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}))} · ${esc(x.league)}</small></span><i>×</i></button>`).join(''):'<p class="sub">Напоминаний пока нет.</p>';$$('[data-reminder-remove]',host).forEach(b=>b.onclick=()=>{const x=entries[Number(b.dataset.reminderRemove)],all=mobileSportReminderStore(),old=x&&all[x.id];if(!old)return;all[x.id]={...old,on:false,ts:Math.max(Date.now(),Number(old.ts||0)+1)};save();draw();});};$('[data-reminder-close]',sheet).onclick=closeSheet;draw();}
